/// <reference types="node" />
/**
 * Type-checks clients generated by `melange generate client --runtime
 * typescript` against this package.
 *
 * test/fixtures/clientgen holds the generator's output for
 * test/testutil/testdata/schema.fga (a Go test keeps it current; regenerate
 * with `just update-golden`) and check.ts, which uses it the way an
 * application would. tsc must accept them with @pthm/melange resolved to src.
 */

import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { describe, expect, test } from 'vitest';

const tsc = fileURLToPath(new URL('../node_modules/typescript/bin/tsc', import.meta.url));
const project = fileURLToPath(new URL('../test/fixtures/clientgen/tsconfig.json', import.meta.url));

describe('generated client', () => {
  test('type-checks', () => {
    let output = '';
    try {
      execFileSync(process.execPath, [tsc, '-p', project], { encoding: 'utf8', stdio: 'pipe' });
    } catch (err) {
      const e = err as { stdout?: string; stderr?: string };
      output = `${e.stdout ?? ''}${e.stderr ?? ''}` || String(err);
    }
    expect(output).toBe('');
  }, 60_000);

  // Imported by URL: the fixtures are outside this package's rootDir, so a
  // static import would break the build.
  type NameMap = Record<string, Record<string, string>>;
  const sql = (dir: string) =>
    import(new URL(`../test/fixtures/clientgen/${dir}/sql.ts`, import.meta.url).href) as Promise<{
      AccessibleFunctions: NameMap;
      AccessibleByParentFunctions: Record<string, Record<string, Record<string, string>>>;
    }>;

  test('maps the installed accessible function names', async () => {
    const { AccessibleFunctions, AccessibleByParentFunctions } = await sql('schema');
    expect(AccessibleFunctions.issue.can_read).toBe('accessible_issue_can_read');
    expect(AccessibleFunctions.pull_request.can_read_security_advisories_and_vulnerability_reports).toBe(
      'accessible_pull_re_can_read_security_advisories_and_vu_d0edb52c',
    );
    expect(AccessibleByParentFunctions.repository.can_deploy.org).toBe('accessible_repository_can_deploy_by_org');
    for (const relations of Object.values(AccessibleFunctions)) {
      for (const name of Object.values(relations)) {
        expect(name.length).toBeLessThanOrEqual(63);
      }
    }
  });

  test('maps are empty when the families are off', async () => {
    const noAccessible = await sql('schema-no-accessible');
    expect(noAccessible.AccessibleFunctions).toEqual({});
    expect(noAccessible.AccessibleByParentFunctions).toEqual({});
  });
});
